fn is_dangerous_e2(bytes: &[u8], i: usize) -> bool {
    // U+200B..D (zero-width), U+202A..E (bidi controls), U+2066..9 (isolates).
    matches!(
        (bytes.get(i + 1), bytes.get(i + 2)),
        (Some(0x80), Some(0x8B..=0x8D | 0xAA..=0xAE)) | (Some(0x81), Some(0xA6..=0xA9))
    )
}
